('REV001MGR001','MGR001','Eneanoh Mmachimerem Ugonna','Head of Operations','CYC001','2026 Mid-Year Performance Cycle','Submitted','I have learnt to be flexible to adapt and adapt to any new development within the company\'s operations and deliver at the best required. ',NULL,NULL,0,'[{\"id\":\"OBJ_OTHER_1\",\"text\":\"Service Delivery & Timeliness\",\"weight\":20,\"type\":\"objective\",\"departments\":[\"Head of Operations\"],\"description\":[\"Ensure 95% on-time service delivery for scheduled operations\",\"Reduce vehicle downtime to less than 10% per month\",\"Ensure 100% compliance with operational safety and regulatory standards\"],\"selfScore\":90},{\"id\":\"OBJ_OTHER_2\",\"text\":\"Operational Staff Policy Compliance\",\"weight\":20,\"type\":\"objective\",\"departments\":[\"Head of Operations\"],\"description\":[\"Achieve 90%+ operational staff performance compliance with company policies\"],\"selfScore\":100},{\"id\":\"OBJ_COMP_1\",\"text\":\"Leadership and Accountability\",\"weight\":10,\"type\":\"competency\",\"expectedLevel\":4,\"category\":\"Leadership\",\"description\":[\"Demonstrate responsibility and ownership of task outcomes\",\"Lead by example and guide colleagues\",\"Maintain accountability for deliverables\"],\"selfScore\":5},{\"id\":\"OBJ_COMP_2\",\"text\":\"Initiative and Perseverance\",\"weight\":10,\"type\":\"competency\",\"expectedLevel\":4,\"category\":\"Behavioural\",\"description\":[\"Take proactive steps to resolve issues without waiting for instructions\",\"Persist in overcoming obstacles and difficulties\",\"Seek continuous improvements in workflows\"],\"selfScore\":5},{\"id\":\"OBJ_COMP_3\",\"text\":\"Communication and Interpersonal Ability\",\"weight\":10,\"type\":\"competency\",\"expectedLevel\":4,\"category\":\"Behavioural\",\"description\":[\"Communicate clearly and effectively with team members and stakeholders\",\"Listen actively and cooperate well with others\",\"Build constructive work relationships\"],\"selfScore\":4},{\"id\":\"OBJ_COMP_4\",\"text\":\"Work Ethics and Attendance\",\"weight\":10,\"type\":\"competency\",\"expectedLevel\":4,\"category\":\"Culture\",\"description\":[\"Show high reliability and commitment to work tasks\",\"Maintain consistent punctuality and attendance\",\"Adhere strictly to corporate codes of conduct\"],\"selfScore\":5},{\"id\":\"OBJ_COMP_5\",\"text\":\"KPI Deployment for Team Members\",\"weight\":10,\"type\":\"competency\",\"expectedLevel\":4,\"category\":\"Leadership\",\"description\":[\"Clearly define and assign KPIs to direct reports\",\"Regularly monitor and evaluate team member performance\",\"Provide feedback and coaching to help team members achieve targets\"],\"selfScore\":5},{\"id\":\"OBJ_COMP_6\",\"text\":\"Self Improvement\",\"weight\":10,\"type\":\"competency\",\"expectedLevel\":4,\"category\":\"Self-Development\",\"description\":[\"Set personal development goals aligned with organizational objectives\",\"Actively seek feedback and opportunities to learn\",\"Complete training courses or obtain professional certifications\"],\"selfScore\":4}]','2026-07-18 09:27:25.000','I hope to attend one personal training for self development. '),
('REV001MGR002','MGR002','Samali Umoru James','Fleet 6 (Fleet Operations Manager)','CYC001','2026 Mid-Year Performance Cycle','Submitted','',NULL,NULL,2.7337499999999997,'[{\"id\":\"OBJ_FLEET_17\",\"text\":\"Fleet Utilization Rate\",\"weight\":6,\"type\":\"objective\",\"departments\":[\"Fleet 6 (Fleet Operations Manager)\"],\"description\":[\"Maintain a utilization rate of at least 90% of the available fleet\",\"Reduce vehicle downtime to less than 5% of operational hours\",\"Safety, Maintenance, and Compliance\"],\"selfScore\":90,\"comments\":\"Targets are reached at least 98% utilization\"},{\"id\":\"OBJ_FLEET_18\",\"text\":\"Fleet Accident Reduction\",\"weight\":6,\"type\":\"objective\",\"departments\":[\"Fleet 6 (Fleet Operations Manager)\"],\"description\":[\"Reduce accident rate by 20% within the next 12 months\",\"Achieve 100% compliance with all regulatory transport requirements within the next 6 months by conducting regular audits\",\"Ensure 100% adherence to scheduled maintenance for all vehicles\"],\"selfScore\":100,\"comments\":\"We were able to reach 100% accident free due to regular training and information\"},{\"id\":\"OBJ_FLEET_19\",\"text\":\"Operational Efficiency\",\"weight\":6,\"type\":\"objective\",\"departments\":[\"Fleet 6 (Fleet Operations Manager)\"],\"description\":[\"Operational Efficiency\",\"Increase the on-time delivery rate by 15% within the year by optimizing routes and providing driver training\",\"Employee Management and Development\"],\"selfScore\":80,\"comments\":\"Training had always been organized by our clients as well as constant briefing from myself.\"},{\"id\":\"OBJ_FLEET_20\",\"text\":\"Operations Team Professional Development\",\"weight\":6,\"type\":\"objective\",\"departments\":[\"Fleet 6 (Fleet Operations Manager)\"],\"description\":[\"Ensure ≥ 80% of the operation team members complete at least one professional development program related to transport by December 2025\",\"Retain at least 85% of drivers annually\",\"Budget Management\"],\"selfScore\":90,\"comments\":\"This had been achieved already. effective fleet management and customers management\"},{\"id\":\"OBJ_FLEET_21\",\"text\":\"Marketing Budget Compliance\",\"weight\":6,\"type\":\"objective\",\"departments\":[\"Fleet 6 (Fleet Operations Manager)\"],\"description\":[\"Percentage compliance with the allocated marketing budget with a variance of no more than 5%\",\"Business Growth\",\"Achieve a 15% year-over-year growth in revenue from logistics operations\"],\"selfScore\":90,\"comments\":\"Reductions of cost.\"},{\"id\":\"OBJ_FLEET_22\",\"text\":\"Client Retention & Service Delivery\",\"weight\":5,\"type\":\"objective\",\"departments\":[\"Fleet 6 (Fleet Operations Manager)\"],\"description\":[\"Retain 90% of existing clients annually through excellent service delivery\",\"Corporate Bus Deployment\",\"Achieve 100% deployment of staff buses for corporate use before the end of Q4 of the current year\"],\"selfScore\":90,\"comments\":\"closed all tickets before downtown.\"},{\"id\":\"OBJ_FLEET_23\",\"text\":\"Shuttle Fleet Deployment & Scale\",\"weight\":5,\"type\":\"objective\",\"departments\":[\"Fleet 6 (Fleet Operations Manager)\"],\"description\":[\"Deploy and maintain a fleet of at least 50 buses for shuttle services between your assigned region before the end of Q4 of the current year\"],\"selfScore\":80,\"comments\":\"50% of this had been achieved in deploying buses to our vendors.\"},{\"id\":\"OBJ_COMP_1\",\"text\":\"Leadership and Accountability\",\"weight\":10,\"type\":\"competency\",\"expectedLevel\":4,\"category\":\"Leadership\",\"description\":[\"Demonstrate responsibility and ownership of task outcomes\",\"Lead by example and guide colleagues\",\"Maintain accountability for deliverables\"],\"selfScore\":5,\"comments\":\"my maintenance expenses speaks a volume.\"},{\"id\":\"OBJ_COMP_2\",\"text\":\"Initiative and Perseverance\",\"weight\":10,\"type\":\"competency\",\"expectedLevel\":4,\"category\":\"Behavioural\",\"description\":[\"Take proactive steps to resolve issues without waiting for instructions\",\"Persist in overcoming obstacles and difficulties\",\"Seek continuous improvements in workflows\"],\"selfScore\":5,\"comments\":\"All tickets are closed before escalations.\"},{\"id\":\"OBJ_COMP_3\",\"text\":\"Communication and Interpersonal Ability\",\"weight\":10,\"type\":\"competency\",\"expectedLevel\":4,\"category\":\"Behavioural\",\"description\":[\"Communicate clearly and effectively with team members and stakeholders\",\"Listen actively and cooperate well with others\",\"Build constructive work relationships\"],\"selfScore\":5,\"comments\":\"My relationships with vendors has assist in achieving most of the goals.\"},{\"id\":\"OBJ_COMP_4\",\"text\":\"Work Ethics and Attendance\",\"weight\":10,\"type\":\"competency\",\"expectedLevel\":4,\"category\":\"Culture\",\"description\":[\"Show high reliability and commitment to work tasks\",\"Maintain consistent punctuality and attendance\",\"Adhere strictly to corporate codes of conduct\"],\"selfScore\":5,\"comments\":\"100% adherence to fleet codes of conducts.\"},{\"id\":\"OBJ_COMP_5\",\"text\":\"KPI Deployment for Team Members\",\"weight\":10,\"type\":\"competency\",\"expectedLevel\":4,\"category\":\"Leadership\",\"description\":[\"Clearly define and assign KPIs to direct reports\",\"Regularly monitor and evaluate team member performance\",\"Provide feedback and coaching to help team members achieve targets\"],\"selfScore\":4,\"comments\":\"Constant reminders of the dos and donts.\"},{\"id\":\"OBJ_COMP_6\",\"text\":\"Self Improvement\",\"weight\":10,\"type\":\"competency\",\"expectedLevel\":4,\"category\":\"Self-Development\",\"description\":[\"Set personal development goals aligned with organizational objectives\",\"Actively seek feedback and opportunities to learn\",\"Complete training courses or obtain professional certifications\"],\"selfScore\":5,\"comments\":\"LSOM, Security awareness training, safety training\"}]','2026-07-15 14:43:26.000','Goals set for the mid year are at 90% achieved both career, spiritual and my professions.'),
('REV001MGR003','MGR003','Buoro Abubakar Idris','Fleet 6 (Fleet Operations Manager)','CYC001','2026 Mid-Year Performance Cycle','Submitted','Performance Highlights\n\nBoosted Fleet Uptime: Achieved a 15% increase in truck availability through a newly implemented preventive maintenance program.\n\n\n\nEnhanced Safety Compliance: Attained a 100% DOT compliance rating and cut road accidents by 25% via targeted driver safety training.\n\n\nImproved Driver Retention: Decreased driver turnover by 18% by establishing a performance-based incentive and recognition program. \n\n\nCareer Development\n\nEarn Professional Certification: Obtain the Certified Fleet Manager (CFM) credential to deepen strategic asset management skills.\n',NULL,NULL,2.60925,'[{\"id\":\"OBJ_FLEET_17\",\"text\":\"Fleet Utilization Rate\",\"weight\":6,\"type\":\"objective\",\"departments\":[\"Fleet 6 (Fleet Operations Manager)\"],\"description\":[\"Maintain a utilization rate of at least 90% of the available fleet\",\"Reduce vehicle downtime to less than 5% of operational hours\",\"Safety, Maintenance, and Compliance\"],\"selfScore\":90},{\"id\":\"OBJ_FLEET_18\",\"text\":\"Fleet Accident Reduction\",\"weight\":6,\"type\":\"objective\",\"departments\":[\"Fleet 6 (Fleet Operations Manager)\"],\"description\":[\"Reduce accident rate by 20% within the next 12 months\",\"Achieve 100% compliance with all regulatory transport requirements within the next 6 months by conducting regular audits\",\"Ensure 100% adherence to scheduled maintenance for all vehicles\"],\"selfScore\":100},{\"id\":\"OBJ_FLEET_19\",\"text\":\"Operational Efficiency\",\"weight\":6,\"type\":\"objective\",\"departments\":[\"Fleet 6 (Fleet Operations Manager)\"],\"description\":[\"Operational Efficiency\",\"Increase the on-time delivery rate by 15% within the year by optimizing routes and providing driver training\",\"Employee Management and Development\"],\"selfScore\":80},{\"id\":\"OBJ_FLEET_20\",\"text\":\"Operations Team Professional Development\",\"weight\":6,\"type\":\"objective\",\"departments\":[\"Fleet 6 (Fleet Operations Manager)\"],\"description\":[\"Ensure ≥ 80% of the operation team members complete at least one professional development program related to transport by December 2025\",\"Retain at least 85% of drivers annually\",\"Budget Management\"],\"selfScore\":80},{\"id\":\"OBJ_FLEET_21\",\"text\":\"Marketing Budget Compliance\",\"weight\":6,\"type\":\"objective\",\"departments\":[\"Fleet 6 (Fleet Operations Manager)\"],\"description\":[\"Percentage compliance with the allocated marketing budget with a variance of no more than 5%\",\"Business Growth\",\"Achieve a 15% year-over-year growth in revenue from logistics operations\"],\"selfScore\":70},{\"id\":\"OBJ_FLEET_22\",\"text\":\"Client Retention & Service Delivery\",\"weight\":5,\"type\":\"objective\",\"departments\":[\"Fleet 6 (Fleet Operations Manager)\"],\"description\":[\"Retain 90% of existing clients annually through excellent service delivery\",\"Corporate Bus Deployment\",\"Achieve 100% deployment of staff buses for corporate use before the end of Q4 of the current year\"],\"selfScore\":90},{\"id\":\"OBJ_FLEET_23\",\"text\":\"Shuttle Fleet Deployment & Scale\",\"weight\":5,\"type\":\"objective\",\"departments\":[\"Fleet 6 (Fleet Operations Manager)\"],\"description\":[\"Deploy and maintain a fleet of at least 50 buses for shuttle services between your assigned region before the end of Q4 of the current year\"],\"selfScore\":80},{\"id\":\"OBJ_COMP_1\",\"text\":\"Leadership and Accountability\",\"weight\":10,\"type\":\"competency\",\"expectedLevel\":4,\"category\":\"Leadership\",\"description\":[\"Demonstrate responsibility and ownership of task outcomes\",\"Lead by example and guide colleagues\",\"Maintain accountability for deliverables\"],\"selfScore\":5},{\"id\":\"OBJ_COMP_2\",\"text\":\"Initiative and Perseverance\",\"weight\":10,\"type\":\"competency\",\"expectedLevel\":4,\"category\":\"Behavioural\",\"description\":[\"Take proactive steps to resolve issues without waiting for instructions\",\"Persist in overcoming obstacles and difficulties\",\"Seek continuous improvements in workflows\"],\"selfScore\":5},{\"id\":\"OBJ_COMP_3\",\"text\":\"Communication and Interpersonal Ability\",\"weight\":10,\"type\":\"competency\",\"expectedLevel\":4,\"category\":\"Behavioural\",\"description\":[\"Communicate clearly and effectively with team members and stakeholders\",\"Listen actively and cooperate well with others\",\"Build constructive work relationships\"],\"selfScore\":5},{\"id\":\"OBJ_COMP_4\",\"text\":\"Work Ethics and Attendance\",\"weight\":10,\"type\":\"competency\",\"expectedLevel\":4,\"category\":\"Culture\",\"description\":[\"Show high reliability and commitment to work tasks\",\"Maintain consistent punctuality and attendance\",\"Adhere strictly to corporate codes of conduct\"],\"selfScore\":5},{\"id\":\"OBJ_COMP_5\",\"text\":\"KPI Deployment for Team Members\",\"weight\":10,\"type\":\"competency\",\"expectedLevel\":4,\"category\":\"Leadership\",\"description\":[\"Clearly define and assign KPIs to direct reports\",\"Regularly monitor and evaluate team member performance\",\"Provide feedback and coaching to help team members achieve targets\"],\"selfScore\":4},{\"id\":\"OBJ_COMP_6\",\"text\":\"Self Improvement\",\"weight\":10,\"type\":\"competency\",\"expectedLevel\":4,\"category\":\"Self-Development\",\"description\":[\"Set personal development goals aligned with organizational objectives\",\"Actively seek feedback and opportunities to learn\",\"Complete training courses or obtain professional certifications\"],\"selfScore\":4}]','2026-07-16 10:03:08.000','As a Fleet Operations Manager, my primary focus for the next review cycle is to shift our fleet from reactive firefighting to a proactive, data-driven operation. \n\nBy focusing on cost containment, asset uptime, and safety, I will directly support our organization’s New Era Transport Services with bottom-line growth.\n\n- Optimize Fleet Maintenance and Reduce Unplanned Downtime\n\n- Control and Reduce Fleet Operational Costs\n\n-Elevate Driver Safety and Behavioral Compliance'),
('REV001MGR004','MGR004','Chidimma Maureen Uzoukwu','NOC 1 (Fleet Monitoring & NOC Supervisor)','CYC001','2026 Mid-Year Performance Cycle','Manager Reviewed','I consistently demonstrated commitment, reliability, and accountability in carrying out my responsibilities. I achieved timely incident reporting and escalation, maintained accurate monitoring logs and reports, ensured effective communication with my line manager and various NBC supervisors, and contributed to seamless NOC operations through proactive problem-solving and teamwork. I upheld high standards of professionalism, punctuality, and adherence to company policies while fostering positive working relationships and supporting team objectives. My ability to take initiative, communicate effectively, and maintain operational excellence contributed significantly to the achievement of departmental and organizational goals.\\n\\nCareer Development Goals\\n\\nGoing forward, I aim to further strengthen my technical and leadership capabilities by pursuing relevant training and professional certifications, enhancing my incident management and monitoring expertise, and developing stronger people management and coaching skills. I will continue to seek feedback, embrace learning opportunities, and identify process improvement initiatives that drive operational efficiency and support the organization’s strategic objectives. My goal is to grow into a higher leadership role while consistently delivering value and contributing to the success of the organization.','',NULL,8.017,'[{\"id\":\"OBJ_NOC_1\",\"text\":\"Fleet Visibility & Monitoring\",\"weight\":7,\"type\":\"objective\",\"departments\":[\"NOC 1 (Fleet Monitoring & NOC Supervisor)\"],\"description\":[\"Maintain 100% real-time tracking visibility for all active fleet vehicles\",\"Ensure all vehicle movements are logged and monitored without gaps\"],\"comments\":\"\\n\\nI successfully maintained 100% real-time visibility of all active NBC And all STAFF BUS  fleet vehicles by ensuring continuous monitoring through Nova Tracking and Insight software platforms. I consistently monitored vehicle locations, movement activities, and tracking status to ensure all fleet operations were visible and properly recorded.\\n\\nI achieved the target of maintaining complete vehicle movement logging with no tracking gaps by conducting regular checks, identifying exceptions promptly, and ensuring tracking devices and systems remained active and reliable. Through effective use of the tracking platforms, I supported improved fleet control, driver accountability, route monitoring, and timely operational decision-making.\",\"selfScore\":90,\"managerScore\":80},{\"id\":\"OBJ_NOC_2\",\"text\":\"Driver Compliance\",\"weight\":7,\"type\":\"objective\",\"departments\":[\"NOC 1 (Fleet Monitoring & NOC Supervisor)\"],\"description\":[\"Detect and report 100% of major driver violations (speeding, route deviation, unauthorized stops)\",\"Achieve at least 90–95% driver compliance with approved routes and policies\"],\"comments\":\"I effectively supported driver compliance by monitoring driver activities and ensuring adherence to approved routes, safety procedures, and operational policies. I detected and reported major driver violations, including speeding, route deviations, and unauthorized stops, through continuous monitoring and timely escalation.\\n\\nTo improve compliance levels, I maintained regular communication with supervisors and drivers across the fleet, providing reminders and reinforcing the importance of following approved routes and company policies. This proactive engagement helped improve driver awareness, accountability, and adherence to operational standards.\",\"selfScore\":90,\"managerScore\":80},{\"id\":\"OBJ_NOC_3\",\"text\":\"Incident Response\",\"weight\":7,\"type\":\"objective\",\"departments\":[\"NOC 1 (Fleet Monitoring & NOC Supervisor)\"],\"description\":[\"Ensure 100% of incidents are reported and escalated within 10–15 minutes of detection\",\"Maintain complete and accurate incident logs for all reported cases\"],\"selfScore\":90,\"comments\":\"Achieved 100% compliance in timely incident reporting and escalation within 10–15 minutes of detection by promptly notifying supervisors and my line manager when necessary, while maintaining accurate and complete incident records for all cases handled.\",\"managerScore\":70},{\"id\":\"OBJ_NOC_4\",\"text\":\"Fuel Monitoring Support\",\"weight\":7,\"type\":\"objective\",\"departments\":[\"NOC 1 (Fleet Monitoring & NOC Supervisor)\"],\"description\":[\"Identify and report 100% of fuel anomalies within 24 hours\",\"Support reduction of fuel-related inefficiencies by 5–10% annually\"],\"comments\":\"Not my JD.\",\"selfScore\":0,\"managerScore\":80},{\"id\":\"OBJ_NOC_5\",\"text\":\"Reporting & Data Accuracy\",\"weight\":6,\"type\":\"objective\",\"departments\":[\"NOC 1 (Fleet Monitoring & NOC Supervisor)\"],\"description\":[\"Submit 100% of required monitoring reports on schedule\",\"Maintain data accuracy rate of at least 98–100% across monitoring logs and reports\"],\"selfScore\":90,\"comments\":\"Achieved 100% on-time submission of monitoring reports to the various NBC supervisors on a daily basis and to my line manager as and when due or upon request, while maintaining a 98–100% data accuracy rate in monitoring logs and reports.\",\"managerScore\":90},{\"id\":\"OBJ_NOC_6\",\"text\":\"Team Performance\",\"weight\":6,\"type\":\"objective\",\"departments\":[\"NOC 1 (Fleet Monitoring & NOC Supervisor)\"],\"description\":[\"Ensure 100% NOC shift coverage as scheduled\",\"Achieve at least 90% adherence to monitoring and escalation procedures by team members\"],\"comments\":\"Achieved 100% NOC shift coverage as scheduled and ensured over 90% adherence to monitoring and escalation procedures through effective teamwork, timely communication, and consistent operational support.\",\"selfScore\":90,\"managerScore\":80},{\"id\":\"OBJ_COMP_1\",\"text\":\"Leadership and Accountability\",\"weight\":10,\"type\":\"competency\",\"expectedLevel\":4,\"category\":\"Leadership\",\"description\":[\"Demonstrate responsibility and ownership of task outcomes\",\"Lead by example and guide colleagues\",\"Maintain accountability for deliverables\"],\"selfScore\":5,\"comments\":\"Demonstrated strong leadership by consistently leading by example and providing guidance to colleagues, while maintaining full accountability for operational activities and communication deliverables\",\"managerScore\":4},{\"id\":\"OBJ_COMP_2\",\"text\":\"Initiative and Perseverance\",\"weight\":10,\"type\":\"competency\",\"expectedLevel\":4,\"category\":\"Behavioural\",\"description\":[\"Take proactive steps to resolve issues without waiting for instructions\",\"Persist in overcoming obstacles and difficulties\",\"Seek continuous improvements in workflows\"],\"selfScore\":5,\"comments\":\"Demonstrated initiative by proactively resolving issues without waiting for instructions, persistently overcoming challenges, and continuously identifying opportunities to improve workflows and operational efficiency.\",\"managerScore\":4},{\"id\":\"OBJ_COMP_3\",\"text\":\"Communication and Interpersonal Ability\",\"weight\":10,\"type\":\"competency\",\"expectedLevel\":4,\"category\":\"Behavioural\",\"description\":[\"Communicate clearly and effectively with team members and stakeholders\",\"Listen actively and cooperate well with others\",\"Build constructive work relationships\"],\"selfScore\":5,\"comments\":\"Consistently fostered healthy and effective communication with team members and management, promoted teamwork through active listening and collaboration, and maintained positive working relationships that enhanced coordination, problem-solving, and overall team performance.\",\"managerScore\":4},{\"id\":\"OBJ_COMP_4\",\"text\":\"Work Ethics and Attendance\",\"weight\":10,\"type\":\"competency\",\"expectedLevel\":4,\"category\":\"Culture\",\"description\":[\"Show high reliability and commitment to work tasks\",\"Maintain consistent punctuality and attendance\",\"Adhere strictly to corporate codes of conduct\"],\"comments\":\"Demonstrated high reliability and commitment by consistently delivering assigned tasks with minimal supervision, meeting deadlines, and supporting team objectives. Maintained excellent punctuality and attendance, remained dependable during critical operations, and willingly collaborated with colleagues to ensure seamless workflow and service delivery. Strictly adhered to corporate policies, procedures, and codes of conduct, while exhibiting professionalism, accountability, and a strong work ethic in all responsibilities.\",\"selfScore\":5,\"managerScore\":4},{\"id\":\"OBJ_COMP_5\",\"text\":\"KPI Deployment for Team Members\",\"weight\":10,\"type\":\"competency\",\"expectedLevel\":4,\"category\":\"Leadership\",\"description\":[\"Clearly define and assign KPIs to direct reports\",\"Regularly monitor and evaluate team member performance\",\"Provide feedback and coaching to help team members achieve targets\"],\"selfScore\":4,\"comments\":\"Successfully deployed and communicated KPIs to team members by clearly defining expectations and performance targets. Regularly monitored and evaluated team performance, provided timely feedback and coaching, and supported team members in achieving their assigned objectives and improving overall performance.\",\"managerScore\":4},{\"id\":\"OBJ_COMP_6\",\"text\":\"Self Improvement\",\"weight\":10,\"type\":\"competency\",\"expectedLevel\":4,\"category\":\"Self-Development\",\"description\":[\"Set personal development goals aligned with organizational objectives\",\"Actively seek feedback and opportunities to learn\",\"Complete training courses or obtain professional certifications\"],\"selfScore\":5,\"comments\":\"Demonstrated a commitment to continuous self-improvement by actively seeking feedback, embracing learning opportunities, and enhancing my skills to align with organizational objectives. Participated in relevant training programs and pursued professional development initiatives to improve performance, increase efficiency, and contribute more effectively to team and organizational goals.\",\"managerScore\":4}]','2026-07-16 09:55:01.000','To improve my technical, communication, and leadership skills while strengthening engagement with drivers and other stakeholders, thereby contributing more effectively to operational excellence and organizational success'),
('REV001MGR005','MGR005','Oluwasijibomi Ebenezer Akinsohun','Head of Operations','CYC001','2026 Mid-Year Performance Cycle','Submitted','I have consistently delivered strong results across service delivery, safety compliance, and staff performance, while demonstrating leadership, accountability, and initiative in overcoming operational challenges. My focus on clear communication, constructive relationships, and proactive problem‑solving has supported team efficiency and improved workflow outcomes.\n\nOn personal development, I completed courses in emotional intelligence and conflict resolution, which enhanced my ability to manage relationships and resolve issues effectively. I continue to actively seek feedback, refine my skills, and align my growth with organizational objectives to sustain high achievement levels and contribute meaningfully to overall success.',NULL,NULL,2.94,'[{\"id\":\"OBJ_OTHER_1\",\"text\":\"Service Delivery & Timeliness\",\"weight\":20,\"type\":\"objective\",\"departments\":[\"Head of Operations\"],\"description\":[\"Ensure 95% on-time service delivery for scheduled operations\",\"Reduce vehicle downtime to less than 10% per month\",\"Ensure 100% compliance with operational safety and regulatory standards\"],\"selfScore\":100,\"comments\":\"Consistently achieved an average of 94–95% on‑time service delivery across scheduled operations (IHS, NBC Mushin, NBC Ikeja, NBC Ikoyi, Ibadan Asejire, YNV, & 100% Rentals buses) demonstrating strong operational discipline.\\n\\nReduced vehicle downtime to below the 10% monthly threshold through proactive maintenance scheduling and improved coordination with workshop teams.\\n\\nMaintained 96% compliance with operational safety standards and regulatory requirements, with little or no recorded violations or penalties.\"},{\"id\":\"OBJ_OTHER_2\",\"text\":\"Operational Staff Policy Compliance\",\"weight\":20,\"type\":\"objective\",\"departments\":[\"Head of Operations\"],\"description\":[\"Achieve 90%+ operational staff performance compliance with company policies\"],\"comments\":\"Achieved over 90% compliance with company policies among operational staff, meeting the set target.\\n\\nConducted regular policy awareness sessions and refresher trainings, ensuring staff understood and adhered to operational standards and company Vision and Mission.\\n\\nImplemented monitoring tools and compliance checklists that reduced policy breaches and improved accountability.\",\"selfScore\":100},{\"id\":\"OBJ_COMP_1\",\"text\":\"Leadership and Accountability\",\"weight\":10,\"type\":\"competency\",\"expectedLevel\":4,\"category\":\"Leadership\",\"description\":[\"Demonstrate responsibility and ownership of task outcomes\",\"Lead by example and guide colleagues\",\"Maintain accountability for deliverables\"],\"comments\":\"Consistently demonstrated responsibility and ownership of assigned tasks, ensuring deliverables were completed on time and to required standards.\\n\\nLed by example through punctuality, adherence to safety protocols, and proactive communication, setting a positive tone for colleagues.\\n\\nProvided guidance and mentorship to team members, helping them navigate operational challenges and improve performance.\\n\\nMaintained accountability for all deliverables, with clear documentation and transparent reporting to management.\",\"selfScore\":5},{\"id\":\"OBJ_COMP_2\",\"text\":\"Initiative and Perseverance\",\"weight\":10,\"type\":\"competency\",\"expectedLevel\":4,\"category\":\"Behavioural\",\"description\":[\"Take proactive steps to resolve issues without waiting for instructions\",\"Persist in overcoming obstacles and difficulties\",\"Seek continuous improvements in workflows\"],\"selfScore\":5,\"comments\":\"Consistently took proactive steps to resolve operational issues without waiting for instructions, ensuring minimal disruption to service delivery.\\n\\nDemonstrated perseverance in overcoming obstacles such as unexpected vehicle breakdowns, regulatory changes, and resource constraints, maintaining service continuity.\\n\\nInitiated workflow improvements, including streamlined reporting processes and enhanced coordination between dispatch and maintenance teams, which reduced delays and improved efficiency.\"},{\"id\":\"OBJ_COMP_3\",\"text\":\"Communication and Interpersonal Ability\",\"weight\":10,\"type\":\"competency\",\"expectedLevel\":4,\"category\":\"Behavioural\",\"description\":[\"Communicate clearly and effectively with team members and stakeholders\",\"Listen actively and cooperate well with others\",\"Build constructive work relationships\"],\"selfScore\":5,\"comments\":\"Enhance communication effectiveness by adopting more digital collaboration tools for real‑time updates. (whatsapp meeting, Google map for Vehicles distance calculation)\\n\\nContinue developing interpersonal skills through leadership workshops and peer feedback sessions.\\n\\nStrengthen stakeholder engagement by scheduling regular review meetings and sharing performance dashboards.\\n\\nAim to build deeper trust and cooperation by encouraging transparent dialogue and recognizing contributions across the team.\\n\\n✨ This entry positions you as someone who not only communicates well but also actively builds relationships that support operational success.\\n\\nWould you like me to now compile all your appraisal items (Service Delivery, Policy Compliance, Leadership, Initiative, Communication) into one cohesive mid‑year self‑appraisal draft, so you have a complete narrative ready to submit in your performance review system?\"},{\"id\":\"OBJ_COMP_4\",\"text\":\"Work Ethics and Attendance\",\"weight\":10,\"type\":\"competency\",\"expectedLevel\":4,\"category\":\"Culture\",\"description\":[\"Show high reliability and commitment to work tasks\",\"Maintain consistent punctuality and attendance\",\"Adhere strictly to corporate codes of conduct\"],\"selfScore\":5,\"comments\":\" I consistently demonstrated reliability in completing tasks, maintained punctual attendance, and adhered strictly to corporate codes of conduct.\"},{\"id\":\"OBJ_COMP_5\",\"text\":\"KPI Deployment for Team Members\",\"weight\":10,\"type\":\"competency\",\"expectedLevel\":4,\"category\":\"Leadership\",\"description\":[\"Clearly define and assign KPIs to direct reports\",\"Regularly monitor and evaluate team member performance\",\"Provide feedback and coaching to help team members achieve targets\"],\"selfScore\":4,\"comments\":\" I clearly defined and assigned KPIs to all direct reports, regularly monitored performance, and provided structured coaching that enabled most team members to meet or exceed their targets.\"},{\"id\":\"OBJ_COMP_6\",\"text\":\"Self Improvement\",\"weight\":10,\"type\":\"competency\",\"expectedLevel\":4,\"category\":\"Self-Development\",\"description\":[\"Set personal development goals aligned with organizational objectives\",\"Actively seek feedback and opportunities to learn\",\"Complete training courses or obtain professional certifications\"],\"comments\":\" I set personal development goals aligned with organizational objectives, completing courses in emotional intelligence and conflict resolution which greatly improved my ability to manage relationships and resolve issues effectively.\",\"selfScore\":4}]','2026-07-16 12:17:37.000','Service Delivery & Timeliness: Maintain current strong performance and continue leveraging route optimization and preventive maintenance to sustain >95% on‑time delivery.\n\nPolicy Compliance: Develop a structured system of daily, weekly, and monthly reports tracking each operation’s expenses versus revenue, boosting financial accountability and strengthening compliance oversight.\n\nLeadership & Accountability: Enhance delegation and mentorship to build stronger team ownership of deliverables.\n\nInitiative & Perseverance: Establish contingency plans for recurring challenges and embed resilience practices across the team.\n\nCommunication & Interpersonal Ability: Adopt digital collaboration tools and schedule regular stakeholder reviews to improve clarity and trust.\n\nWork Ethics & Attendance: Reinforce punctuality and task prioritization while maintaining strict adherence to codes of conduct.\n\nKPI Deployment: Refine KPI frameworks, monitor performance with dashboards, and provide timely coaching to sustain high achievement.\n\nSelf‑Improvement: Continue applying emotional intelligence and conflict resolution skills, seek feedback actively, and pursue further certifications to align with organizational objectives.'),
('REV001MGR006','MGR006','Arotile Rotimi Seyi','Finance 5 (Head of Finance)','CYC001','2026 Mid-Year Performance Cycle','Submitted','I worked with the external auditor for the preparation of AFS, coordinate the new member of the finance team and prepare and provide necessary financial date when needed',NULL,NULL,2.4097499999999994,'[{\"id\":\"OBJ_FINANCE_ACCOUNTS_24\",\"text\":\"Operational Cost Reduction\",\"weight\":7,\"type\":\"objective\",\"departments\":[\"Finance 5 (Head of Finance)\"],\"description\":[\"Reduce operating costs by 10% across the board by Q4 through process optimization and vendor negotiations\",\"Cost Savings Ratio: Percentage of costs saved compared to the previous period\",\"Financial Management\"],\"selfScore\":80,\"comments\":\"from january to june , 2025, there is a cost saving of 22%. \"},{\"id\":\"OBJ_FINANCE_ACCOUNTS_25\",\"text\":\"Liquidity & Cash Flow Management\",\"weight\":7,\"type\":\"objective\",\"departments\":[\"Finance 5 (Head of Finance)\"],\"description\":[\"Maintain a minimum cash reserve of ₦100 million at all times to ensure liquidity and financial stability\",\"Cash Flow Management\",\"Maintain a minimum cash reserve equivalent to 3 months of operating expenses by ensuring effective receivables and payables management every quarter\"],\"selfScore\":50,\"comments\":\"the debtor collection period is less than the ideal collection period of 30 days. our invoices are always paid before 30 days.\"},{\"id\":\"OBJ_FINANCE_ACCOUNTS_26\",\"text\":\"Budget Adherence & Control\",\"weight\":7,\"type\":\"objective\",\"departments\":[\"Finance 5 (Head of Finance)\"],\"description\":[\"Budget Adherence\",\"Ensure 95% adherence to the annual operating budget with monthly variance analysis reports submitted by the 5th of each month\",\"Debt Management\"],\"selfScore\":80,\"comments\":\"our weekly and monthly budget helps to monitor and control the expenses. We have about 20% on cost saving on fleet repairs and maintenance\"},{\"id\":\"OBJ_FINANCE_ACCOUNTS_27\",\"text\":\"Debt Collection & Recovery\",\"weight\":7,\"type\":\"objective\",\"departments\":[\"Finance 5 (Head of Finance)\"],\"description\":[\"Reduce outstanding debts by 15% by the end of FY 2025 by improving collection efficiency and renegotiating payment terms with clients and suppliers\",\"Employee Development\",\"Ensure 80% of finance team members complete at least one professional development program related to transport finance by the end of the year\"],\"comments\":\"within the past two months, I have trained victoria and bukola on advance excel formula and pivotal table  which ease preparation of weekly and monthly report. Also, I have started teaching Joyce on Excel. I told victoria and bukola to enrol in one course and presently, Victoria is taking financial modelling course and Bukola is taking data analysis course\",\"selfScore\":80},{\"id\":\"OBJ_FINANCE_ACCOUNTS_28\",\"text\":\"Risk Management And Compliance\",\"weight\":6,\"type\":\"objective\",\"departments\":[\"Finance 5 (Head of Finance)\"],\"description\":[\"Risk Management and Compliance\",\"Implement a robust risk management framework within the next 6 months to identify, assess, and mitigate financial risks\",\"Achieve 100% compliance with financial regulations and laws within the next 3 months by conducting regular audits and reviews\"],\"selfScore\":60,\"comments\":\"we carryout the risk exposure especially compliance risk and try to come up with statutory payment schedule to monitor the payment\"},{\"id\":\"OBJ_FINANCE_ACCOUNTS_29\",\"text\":\"Reporting\",\"weight\":6,\"type\":\"objective\",\"departments\":[\"Finance 5 (Head of Finance)\"],\"description\":[\"Reporting\",\"Prepare and submit the weekly financial performance report (FPRs) for New Era/Nets Logistics/ KHLC/ Shuttle/ Rental Bus in the first week of the new month\"],\"selfScore\":100,\"comments\":\"we prepare weekly, monthly and quarterly report as at when due\"},{\"id\":\"OBJ_COMP_1\",\"text\":\"Leadership and Accountability\",\"weight\":10,\"type\":\"competency\",\"expectedLevel\":4,\"category\":\"Leadership\",\"description\":[\"Demonstrate responsibility and ownership of task outcomes\",\"Lead by example and guide colleagues\",\"Maintain accountability for deliverables\"],\"selfScore\":5,\"comments\":\"I am friendly with finance staff and caution them when the need arises\"},{\"id\":\"OBJ_COMP_2\",\"text\":\"Initiative and Perseverance\",\"weight\":10,\"type\":\"competency\",\"expectedLevel\":4,\"category\":\"Behavioural\",\"description\":[\"Take proactive steps to resolve issues without waiting for instructions\",\"Persist in overcoming obstacles and difficulties\",\"Seek continuous improvements in workflows\"],\"selfScore\":4,\"comments\":\"I have created some schedules that help in improving the work flow and also used in detecting errors from another party\"},{\"id\":\"OBJ_COMP_3\",\"text\":\"Communication and Interpersonal Ability\",\"weight\":10,\"type\":\"competency\",\"expectedLevel\":4,\"category\":\"Behavioural\",\"description\":[\"Communicate clearly and effectively with team members and stakeholders\",\"Listen actively and cooperate well with others\",\"Build constructive work relationships\"],\"selfScore\":5,\"comments\":\"communication with team member is always my priority. it helps to improve efficiency within the team\"},{\"id\":\"OBJ_COMP_4\",\"text\":\"Work Ethics and Attendance\",\"weight\":10,\"type\":\"competency\",\"expectedLevel\":4,\"category\":\"Culture\",\"description\":[\"Show high reliability and commitment to work tasks\",\"Maintain consistent punctuality and attendance\",\"Adhere strictly to corporate codes of conduct\"],\"comments\":\"I am very punctual to work and use to do list to accomplish my daily task\",\"selfScore\":4},{\"id\":\"OBJ_COMP_5\",\"text\":\"KPI Deployment for Team Members\",\"weight\":10,\"type\":\"competency\",\"expectedLevel\":4,\"category\":\"Leadership\",\"description\":[\"Clearly define and assign KPIs to direct reports\",\"Regularly monitor and evaluate team member performance\",\"Provide feedback and coaching to help team members achieve targets\"],\"selfScore\":5,\"comments\":\"There is segregation of work and at the end of the day, we ask members what the have achieved\"},{\"id\":\"OBJ_COMP_6\",\"text\":\"Self Improvement\",\"weight\":10,\"type\":\"competency\",\"expectedLevel\":4,\"category\":\"Self-Development\",\"description\":[\"Set personal development goals aligned with organizational objectives\",\"Actively seek feedback and opportunities to learn\",\"Complete training courses or obtain professional certifications\"],\"comments\":\"I have taken financial modelling course this year and I have register for excess bank charges audit  training coming up at the end of the month. I have also started my chartered institute of taxation course.\",\"selfScore\":5}]','2026-07-15 15:18:10.000','To complete training on excess bank charges course this month and  chartered institute of taxation before the end of the year'),
('REV001MGR007','MGR007','Divine Favour Chi Egbomuche','Marketing 1 (Head of Marketing)','CYC001','2026 Mid-Year Performance Cycle','Manager Reviewed','Delivered strong marketing performance by meeting key objectives, supporting business growth, leading initiatives with accountability, and collaborating effectively across teams. I remained committed to continuous learning, improving processes, and contributing to the company\'s success.','Overrall performance for the marketing team for the 1st 6months is good but can be far better. we need alot of focus on online marketing (ability to replicate our online processes and get maximum result) and also engagement of corporate clients for staff bus',NULL,8.11525,'[{\"id\":\"OBJ_MARKETING_1\",\"text\":\"Marketing Revenue Growth\",\"weight\":7,\"type\":\"objective\",\"departments\":[\"Marketing 1 (Head of Marketing)\"],\"description\":[\"Achieve at least 25–35% annual growth in marketing-generated revenue across business units\",\"Ensure a minimum of 40–50% of total company leads originate from marketing activities\",\"Lead Generation & Conversion\"],\"selfScore\":90,\"comments\":\"Total leads generated for the passed six months 9(Jan to June) was 2206,000,across Websites, Whatsapp .\\nTotal Revenue Generated was #28,000,000\\nTotal marketing spent #2,693,437.95.\\n\\nFOR SKILLUP ACADEMY \\nAmount spent on ads #1,228,190\\nTotal amount of leads generated #1,693leads.\\nAmount generated was #1,550,000\\nFOR ORGANIC SALES : \\nWalking customers was #1000 \\nAmount Generated was  for 6months #15.500,000\\n\\n\",\"managerFeedback\":\"This ok. We can do better. We need to streamline the Ads process and get what works. We have alot to do on this\",\"managerScore\":60},{\"id\":\"OBJ_MARKETING_2\",\"text\":\"Qualified Lead Generation\",\"weight\":7,\"type\":\"objective\",\"departments\":[\"Marketing 1 (Head of Marketing)\"],\"description\":[\"Increase qualified lead generation by at least 20–30% annually\",\"Maintain lead-to-customer conversion rate of at least 10–20% in collaboration with the sales team\",\"Brand Visibility & Engagement\"],\"comments\":\"NETs\\nFor Brand Visibility was over 100,000 reached.\\n500 qualified leads from 2,206 customer interactions, achieving a 22.7% lead generation rate.\\n Converted 2,206 enquiries into 500 qualified leads, representing a 22.7% conversion to lead rate.\\n\\nFOR SKILLUP ACADEMY :\\nOut of 1,693leads generated 200,000 leads were converted into sales.\\nBrand Visibility and Engagement was  Interactions: 3k\\nFollowers: 79\\nViews: 788.2k\\nFacebook views increased by 100% in 6 months\\n\",\"selfScore\":100,\"managerFeedback\":\"This ok. We can do better. We need to streamline the Ads process and get what works. We have alot to do on this\",\"managerScore\":70},{\"id\":\"OBJ_MARKETING_3\",\"text\":\"Social Media Reach & Analytics\",\"weight\":7,\"type\":\"objective\",\"departments\":[\"Marketing 1 (Head of Marketing)\"],\"description\":[\"Achieve a minimum of 30% annual growth in social media reach and engagement across platforms\",\"Increase website traffic by at least 25% year-on-year\",\"Maintain consistent brand presence across all major marketing channels\"],\"comments\":\"Nets : Achieved a 50% growth in social media followers, reaching 3,000+ followers from an initial 2,000. Generated over 100,000 in reach, managed 500+ customer enquiries, and supported a 50% conversion rate through effective engagement and follow-up strategies.\\nSKILLUP ACADEMY:\\nSocial media reach: 577.2k\\nResponse rate: 25%\\nVideo performance: 12.9k\\nMessaging contacts: 20%\\n\\n\",\"selfScore\":100,\"managerScore\":70,\"managerFeedback\":\"Whats most important is to create an ad system that works and can be repeated. We have invested so much in this social media project and we need to have a blue print of what works so that it can be replicated\"},{\"id\":\"OBJ_MARKETING_4\",\"text\":\"Campaign Performance\",\"weight\":7,\"type\":\"objective\",\"departments\":[\"Marketing 1 (Head of Marketing)\"],\"description\":[\"Campaign Performance\",\"Deliver 90–95% of marketing campaigns on schedule and within approved budgets\",\"Ensure minimum ROI ratio of 3:1 on major marketing campaigns (where measurable)\"],\"comments\":\"NETs\\n10.39*3 This is the maximum of Return of investment .\\n\\nFOR SKILLUP ACADEMY :\\nAchieved a 26.2% return on advertising investment (ROI), generating ₦1.55 million in revenue from an ad spend of ₦1.23 million.  \\n\",\"selfScore\":100,\"managerScore\":80,\"managerFeedback\":\"The campaign push was very obvious and consistent. Especially for the Skillup and Jamb \"},{\"id\":\"OBJ_MARKETING_5\",\"text\":\"Team Performance & Productivity\",\"weight\":6,\"type\":\"objective\",\"departments\":[\"Marketing 1 (Head of Marketing)\"],\"description\":[\"Team Performance & Productivity\",\"Ensure 100% completion of marketing team performance reviews annually\",\"Maintain high team productivity and campaign output across marketing staff\"],\"selfScore\":100,\"comments\":\"The team consistently delivered marketing activities, customer engagements, promotional campaigns, and lead generation initiatives that supported organizational goals. Continuous coaching, collaboration, and performance monitoring contributed to improved efficiency, accountability, and overall campaign output.\",\"managerScore\":80,\"managerFeedback\":\"There was a great team effort and drive from the marketing dept\"},{\"id\":\"OBJ_MARKETING_6\",\"text\":\"Marketing Objectives Completion Rate\",\"weight\":6,\"type\":\"objective\",\"departments\":[\"Marketing 1 (Head of Marketing)\"],\"description\":[\"Achieve 90%+ completion rate of departmental marketing objectives each quarter\"],\"comments\":\"Achieved over 90% of quarterly marketing objectives through successful campaign execution, increased brand visibility, improved lead generation, and timely delivery of key marketing initiatives aligned with business goals.\",\"selfScore\":90,\"managerFeedback\":\"good effort \",\"managerScore\":70},{\"id\":\"OBJ_COMP_1\",\"text\":\"Leadership and Accountability\",\"weight\":10,\"type\":\"competency\",\"expectedLevel\":4,\"category\":\"Leadership\",\"description\":[\"Demonstrate responsibility and ownership of task outcomes\",\"Lead by example and guide colleagues\",\"Maintain accountability for deliverables\"],\"selfScore\":5,\"comments\":\"Consistently demonstrated leadership by taking ownership of assigned tasks, meeting deadlines, guiding team members, and ensuring deliverables were completed to a high standard while maintaining accountability for results.\",\"managerScore\":4,\"managerFeedback\":\"Good effort -however need to create more leads and to empower subordinates for leadership\"},{\"id\":\"OBJ_COMP_2\",\"text\":\"Initiative and Perseverance\",\"weight\":10,\"type\":\"competency\",\"expectedLevel\":4,\"category\":\"Behavioural\",\"description\":[\"Take proactive steps to resolve issues without waiting for instructions\",\"Persist in overcoming obstacles and difficulties\",\"Seek continuous improvements in workflows\"],\"comments\":\"Proactively identified and resolved challenges, implemented improvements to marketing workflows, consistently followed through on tasks despite obstacles, and took initiative to drive projects forward with minimal supervision.\",\"selfScore\":5,\"managerFeedback\":\"Great effort\",\"managerScore\":4},{\"id\":\"OBJ_COMP_3\",\"text\":\"Communication and Interpersonal Ability\",\"weight\":10,\"type\":\"competency\",\"expectedLevel\":4,\"category\":\"Behavioural\",\"description\":[\"Communicate clearly and effectively with team members and stakeholders\",\"Listen actively and cooperate well with others\",\"Build constructive work relationships\"],\"selfScore\":5,\"managerScore\":3,\"managerFeedback\":\"needs alot of improvement in developing more interpersonal skills and communications with colleagues\"},{\"id\":\"OBJ_COMP_4\",\"text\":\"Work Ethics and Attendance\",\"weight\":10,\"type\":\"competency\",\"expectedLevel\":4,\"category\":\"Culture\",\"description\":[\"Show high reliability and commitment to work tasks\",\"Maintain consistent punctuality and attendance\",\"Adhere strictly to corporate codes of conduct\"],\"selfScore\":5,\"managerScore\":4},{\"id\":\"OBJ_COMP_5\",\"text\":\"KPI Deployment for Team Members\",\"weight\":10,\"type\":\"competency\",\"expectedLevel\":4,\"category\":\"Leadership\",\"description\":[\"Clearly define and assign KPIs to direct reports\",\"Regularly monitor and evaluate team member performance\",\"Provide feedback and coaching to help team members achieve targets\"],\"selfScore\":5,\"comments\":\"> Successfully deployed clear KPIs to team members, monitored performance regularly, provided timely feedback and coaching, and ensured alignment with departmental objectives to improve overall team performance.\",\"managerScore\":5},{\"id\":\"OBJ_COMP_6\",\"text\":\"Self Improvement\",\"weight\":10,\"type\":\"competency\",\"expectedLevel\":4,\"category\":\"Self-Development\",\"description\":[\"Set personal development goals aligned with organizational objectives\",\"Actively seek feedback and opportunities to learn\",\"Complete training courses or obtain professional certifications\"],\"selfScore\":5,\"comments\":\"> Consistently pursued professional development by completing relevant training, applying new skills to improve performance, seeking feedback for continuous improvement, and aligning personal growth with organizational objectives.\",\"managerScore\":4}]','2026-07-28 11:08:51.000','Strengthen digital marketing and data analytics skills, improve campaign performance and lead conversion, mentor team members more effectively, and continue driving innovative strategies that support business growth and achieve departmental goals.'),
('REV001MGR008','MGR008','Emeka Okoro','Internal Control 1 (Internal Control)','CYC001','2026 Mid-Year Performance Cycle','Manager Reviewed','I consistently demonstrated commitment, professionalism, and accountability in carrying out my responsibilities','to undergo fleet management course and improve his knowledge on excel work.',NULL,8.408249999999999,'[{\"id\":\"OBJ_INTERNAL_CONTROL_1\",\"text\":\"Completing Audit Reports\",\"weight\":14,\"type\":\"objective\",\"departments\":[\"Internal Control 1 (Internal Control)\"],\"description\":[\"Completing Audit Reports\",\"Cycle time for completing Draft Audit Reports\",\"Cycle time for completing Final Audit Reports\"],\"selfScore\":80,\"comments\":\"I consistently completed audit report and within the required timeline, i ensured that audit findings were clearly documented \",\"managerFeedback\":\"yes\",\"managerScore\":80},{\"id\":\"OBJ_INTERNAL_CONTROL_2\",\"text\":\"Audit Accuracy & Fraud Detection\",\"weight\":13,\"type\":\"objective\",\"departments\":[\"Internal Control 1 (Internal Control)\"],\"description\":[\"Number of cases of fraud issues detected by 3rd parties (External Auditors) during audit exercises (but not detected by Internal Auditors)\",\"Percentage of transport-related regulations and laws complied with\",\"Percentage of reports completed within timelines\"],\"selfScore\":80,\"comments\":\"I focus on accuracy and attention to detail contributed to reliable audit outcome, strengthened internal control and supported the organization fraud prevention effort\",\"managerFeedback\":\"yes\",\"managerScore\":80},{\"id\":\"OBJ_INTERNAL_CONTROL_3\",\"text\":\"Asset Utilization Optimization\",\"weight\":13,\"type\":\"objective\",\"departments\":[\"Internal Control 1 (Internal Control)\"],\"description\":[\"Percentage of Optimal Asset Utilization\"],\"selfScore\":90,\"comments\":\"I contributed to optimization asset utilization by monitoring the use and condition of organisational assets, identifying underutilized or inefficiently managed resources\",\"managerFeedback\":\"yes\",\"managerScore\":80},{\"id\":\"OBJ_COMP_1\",\"text\":\"Leadership and Accountability\",\"weight\":10,\"type\":\"competency\",\"expectedLevel\":4,\"category\":\"Leadership\",\"description\":[\"Demonstrate responsibility and ownership of task outcomes\",\"Lead by example and guide colleagues\",\"Maintain accountability for deliverables\"],\"selfScore\":4,\"comments\":\"I demonstrated leadership by taking ownership of my responsibilities\",\"managerFeedback\":\"yes\",\"managerScore\":5},{\"id\":\"OBJ_COMP_2\",\"text\":\"Initiative and Perseverance\",\"weight\":10,\"type\":\"competency\",\"expectedLevel\":4,\"category\":\"Behavioural\",\"description\":[\"Take proactive steps to resolve issues without waiting for instructions\",\"Persist in overcoming obstacles and difficulties\",\"Seek continuous improvements in workflows\"],\"selfScore\":4,\"comments\":\"I remained persistent in completing assignments despite challenges  \",\"managerScore\":4,\"managerFeedback\":\"yes\"},{\"id\":\"OBJ_COMP_3\",\"text\":\"Communication and Interpersonal Ability\",\"weight\":10,\"type\":\"competency\",\"expectedLevel\":4,\"category\":\"Behavioural\",\"description\":[\"Communicate clearly and effectively with team members and stakeholders\",\"Listen actively and cooperate well with others\",\"Build constructive work relationships\"],\"selfScore\":4,\"comments\":\"listen actively and cooperate well with others\",\"managerFeedback\":\"friendly with team members\",\"managerScore\":4},{\"id\":\"OBJ_COMP_4\",\"text\":\"Work Ethics and Attendance\",\"weight\":10,\"type\":\"competency\",\"expectedLevel\":4,\"category\":\"Culture\",\"description\":[\"Show high reliability and commitment to work tasks\",\"Maintain consistent punctuality and attendance\",\"Adhere strictly to corporate codes of conduct\"],\"selfScore\":5,\"comments\":\"I consistently demonstrated a strong work ethic and maintained professionalism, integrity, and a high level of commitment\",\"managerScore\":5,\"managerFeedback\":\"good work ethics\"},{\"id\":\"OBJ_COMP_5\",\"text\":\"KPI Deployment for Team Members\",\"weight\":10,\"type\":\"competency\",\"expectedLevel\":4,\"category\":\"Leadership\",\"description\":[\"Clearly define and assign KPIs to direct reports\",\"Regularly monitor and evaluate team member performance\",\"Provide feedback and coaching to help team members achieve targets\"],\"selfScore\":4,\"comments\":\"I communicated expectations clearly, monitored progress where applicable, provided guidance and feedback \",\"managerFeedback\":\"he has good feedback mechanism\",\"managerScore\":5},{\"id\":\"OBJ_COMP_6\",\"text\":\"Self Improvement\",\"weight\":10,\"type\":\"competency\",\"expectedLevel\":4,\"category\":\"Self-Development\",\"description\":[\"Set personal development goals aligned with organizational objectives\",\"Actively seek feedback and opportunities to learn\",\"Complete training courses or obtain professional certifications\"],\"selfScore\":5,\"comments\":\"I remained committed to continuous self-improvement by actively seeking to enhance my knowledge and skills\",\"managerFeedback\":\"yes\",\"managerScore\":5}]','2026-07-16 11:58:18.000','fleet management course'),
('REV001MGR009','MGR009','Solomon Grace Amarachi','KHLC 3 (Program Coordinator)','CYC001','2026 Mid-Year Performance Cycle','Submitted','Performance Summary\n\nSuccessfully coordinated training programs across multiple locations, ensured timely tracking of deliverables, and maintained strong accountability for program execution. Demonstrated effective leadership, organization, and commitment to quality, while identifying opportunities to improve stakeholder engagement.\n\nCareer Goals\n\nTo grow into a senior leadership role in program and education management, driving impactful learning initiatives, strategic partnerships, and organizational growth.\n\nDevelopment Goals\n\nStrengthen stakeholder management, enhance leadership and project management skills, and pursue relevant professional certifications to improve program delivery and operational excellence.',NULL,NULL,2.4584999999999995,'[{\"id\":\"OBJ_COMP_1\",\"text\":\"Leadership and Accountability\",\"weight\":10,\"type\":\"competency\",\"expectedLevel\":4,\"category\":\"Leadership\",\"departments\":null,\"description\":[\"Demonstrate responsibility and ownership of task outcomes\",\"Lead by example and guide colleagues\",\"Maintain accountability for deliverables\"],\"selfScore\":5,\"managerScore\":null,\"comments\":\"Demonstrated strong ownership and accountability for program outcomes by coordinating training activities across Lagos and Ota, monitoring deliverables through weekly reports from Assistant Program Coordinators, and ensuring timely follow-up on assigned tasks. \\nLed by example by providing guidance and support to team members, addressing operational challenges promptly, and maintaining accountability for the successful execution of program activities.\",\"evidence\":null,\"managerFeedback\":null},{\"id\":\"OBJ_COMP_2\",\"text\":\"Initiative and Perseverance\",\"weight\":10,\"type\":\"competency\",\"expectedLevel\":4,\"category\":\"Behavioural\",\"departments\":null,\"description\":[\"Take proactive steps to resolve issues without waiting for instructions\",\"Persist in overcoming obstacles and difficulties\",\"Seek continuous improvements in workflows\"],\"selfScore\":4,\"managerScore\":null,\"comments\":null,\"evidence\":null,\"managerFeedback\":null},{\"id\":\"OBJ_COMP_3\",\"text\":\"Communication and Interpersonal Ability\",\"weight\":10,\"type\":\"competency\",\"expectedLevel\":4,\"category\":\"Behavioural\",\"departments\":null,\"description\":[\"Communicate clearly and effectively with team members and stakeholders\",\"Listen actively and cooperate well with others\",\"Build constructive work relationships\"],\"selfScore\":5,\"managerScore\":null,\"comments\":null,\"evidence\":null,\"managerFeedback\":null},{\"id\":\"OBJ_COMP_4\",\"text\":\"Work Ethics and Attendance\",\"weight\":10,\"type\":\"competency\",\"expectedLevel\":4,\"category\":\"Culture\",\"departments\":null,\"description\":[\"Show high reliability and commitment to work tasks\",\"Maintain consistent punctuality and attendance\",\"Adhere strictly to corporate codes of conduct\"],\"selfScore\":3,\"managerScore\":null,\"comments\":null,\"evidence\":null,\"managerFeedback\":null},{\"id\":\"OBJ_COMP_5\",\"text\":\"KPI Deployment for Team Members\",\"weight\":10,\"type\":\"competency\",\"expectedLevel\":4,\"category\":\"Leadership\",\"departments\":null,\"description\":[\"Clearly define and assign KPIs to direct reports\",\"Regularly monitor and evaluate team member performance\",\"Provide feedback and coaching to help team members achieve targets\"],\"selfScore\":5,\"managerScore\":null,\"comments\":null,\"evidence\":null,\"managerFeedback\":null},{\"id\":\"OBJ_COMP_6\",\"text\":\"Self Improvement\",\"weight\":10,\"type\":\"competency\",\"expectedLevel\":4,\"category\":\"Self-Development\",\"departments\":null,\"description\":[\"Set personal development goals aligned with organizational objectives\",\"Actively seek feedback and opportunities to learn\",\"Complete training courses or obtain professional certifications\"],\"selfScore\":5,\"managerScore\":null,\"comments\":null,\"evidence\":null,\"managerFeedback\":null},{\"id\":\"OBJ_KHLC_3_1\",\"text\":\"Instructor Resource & Equipment Readiness\",\"weight\":6,\"type\":\"objective\",\"expectedLevel\":null,\"category\":null,\"departments\":[\"KHLC 3 (Program Coordinator)\"],\"description\":[\"Ensure instructors are 80% – 90% (i.e., notes, laptops, instructional materials, retooling) equipped, 2 weeks before the commencement of every academic session\"],\"selfScore\":90,\"managerScore\":null,\"comments\":\"Successfully ensured that approximately 90% of instructor resources, including lesson notes and instructional materials, were prepared and distributed at least two weeks before the commencement of the academic session. Distribution of laptops could not be completed due to their unavailability, which was outside my direct control.\",\"evidence\":null,\"managerFeedback\":null},{\"id\":\"OBJ_KHLC_3_2\",\"text\":\"Project Execution & Budget Management\",\"weight\":6,\"type\":\"objective\",\"expectedLevel\":null,\"category\":null,\"departments\":[\"KHLC 3 (Program Coordinator)\"],\"description\":[\"Successfully execute 95% of assigned projects within the agreed timeline and budget\"],\"selfScore\":90,\"managerScore\":null,\"comments\":\"Successfully executed all projects assigned during the review period within the agreed timelines and available budget.\\n Although the volume of assigned projects was lower than anticipated, all responsibilities entrusted to me were completed effectively and met the expected quality standards.\",\"evidence\":null,\"managerFeedback\":null},{\"id\":\"OBJ_KHLC_3_3\",\"text\":\"Feedback Scores & Post-Training Evaluations\",\"weight\":6,\"type\":\"objective\",\"expectedLevel\":null,\"category\":null,\"departments\":[\"KHLC 3 (Program Coordinator)\"],\"description\":[\"Maintain an average feedback score between 80% - 90% on post-training evaluations each quarter\"],\"selfScore\":50,\"managerScore\":null,\"comments\":\"Formal post-training evaluations were not consistently administered during the review period, making it difficult to accurately measure this KPI. Informal learner feedback was positive and indicated satisfaction with the training experience.\",\"evidence\":null,\"managerFeedback\":null},{\"id\":\"OBJ_KHLC_3_4\",\"text\":\"Project Task Timelines\",\"weight\":6,\"type\":\"objective\",\"expectedLevel\":null,\"category\":null,\"departments\":[\"KHLC 3 (Program Coordinator)\"],\"description\":[\"Ensure 100% of assigned project-related tasks are completed within the agreed timelines for each program\"],\"selfScore\":80,\"managerScore\":null,\"comments\":null,\"evidence\":null,\"managerFeedback\":null},{\"id\":\"OBJ_KHLC_3_5\",\"text\":\"Deliverable Tracking & Coordination\",\"weight\":6,\"type\":\"objective\",\"expectedLevel\":null,\"category\":null,\"departments\":[\"KHLC 3 (Program Coordinator)\"],\"description\":[\"Achieve the target of 100% deliverable tracking and coordination by the end of each quarter/ session\"],\"selfScore\":100,\"managerScore\":null,\"comments\":\"Achieved 100% deliverable tracking and coordination through a structured weekly reporting system with the Assistant Program Coordinators. \\nRegular reports enabled effective monitoring of program implementation, timely follow-up on deliverables, and seamless coordination of training activities across Lagos, Ota, and Benin, ensuring that program milestones were consistently tracked throughout each session.\",\"evidence\":null,\"managerFeedback\":null},{\"id\":\"OBJ_KHLC_3_6\",\"text\":\"Stakeholder Relationships\",\"weight\":6,\"type\":\"objective\",\"expectedLevel\":null,\"category\":null,\"departments\":[\"KHLC 3 (Program Coordinator)\"],\"description\":[\"Achieve an average stakeholder relationship rating of 4/5 or higher (>=90%)\"],\"selfScore\":60,\"managerScore\":null,\"comments\":\"Maintained cordial and professional relationships with internal stakeholders, including Assistant Program Coordinators and instructors, to facilitate smooth program execution. \\nHowever, engagement with external stakeholders was limited during the review period, resulting in fewer opportunities to build and measure broader stakeholder relationships against the target.\",\"evidence\":null,\"managerFeedback\":null},{\"id\":\"OBJ_KHLC_3_7\",\"text\":\"Reporting and Documentation\",\"weight\":4,\"type\":\"objective\",\"expectedLevel\":null,\"category\":null,\"departments\":[\"KHLC 3 (Program Coordinator)\"],\"description\":[\"Submit accurate quarterly report before end of term\",\"Ensure 100% of documents are filed (physical and digital) in the appropriate systems within 24 hours of receipt, maintaining 98% accuracy.\"],\"selfScore\":80,\"managerScore\":null,\"comments\":null,\"evidence\":null,\"managerFeedback\":null}]','2026-07-16 11:44:43.000','Strengthen stakeholder engagement through regular communication and feedback, enhance leadership through coaching and delegation, improve program monitoring using digital tracking tools, and pursue continuous professional development in project management and leadership to increase operational effectiveness and program impact.'),
('REV001MGR010','MGR010','Lawal Obanle Promise','KHLC 5 (Head of   C&R/CBT)','CYC001','2026 Mid-Year Performance Cycle','Submitted','initiate Instructors training (Lagos, Ogun and Benin), successfully setup system networking and Jamb exam front start to finish without glitches,  successfully managing the CBT center utility operation.\\n',NULL,NULL,2.9,'[{\"id\":\"OBJ_COMP_1\",\"text\":\"Leadership and Accountability\",\"weight\":10,\"type\":\"competency\",\"expectedLevel\":4,\"category\":\"Leadership\",\"description\":[\"Demonstrate responsibility and ownership of task outcomes\",\"Lead by example and guide colleagues\",\"Maintain accountability for deliverables\"],\"selfScore\":5},{\"id\":\"OBJ_COMP_2\",\"text\":\"Initiative and Perseverance\",\"weight\":10,\"type\":\"competency\",\"expectedLevel\":4,\"category\":\"Behavioural\",\"description\":[\"Take proactive steps to resolve issues without waiting for instructions\",\"Persist in overcoming obstacles and difficulties\",\"Seek continuous improvements in workflows\"],\"selfScore\":5},{\"id\":\"OBJ_COMP_3\",\"text\":\"Communication and Interpersonal Ability\",\"weight\":10,\"type\":\"competency\",\"expectedLevel\":4,\"category\":\"Behavioural\",\"description\":[\"Communicate clearly and effectively with team members and stakeholders\",\"Listen actively and cooperate well with others\",\"Build constructive work relationships\"],\"selfScore\":5},{\"id\":\"OBJ_COMP_4\",\"text\":\"Work Ethics and Attendance\",\"weight\":10,\"type\":\"competency\",\"expectedLevel\":4,\"category\":\"Culture\",\"description\":[\"Show high reliability and commitment to work tasks\",\"Maintain consistent punctuality and attendance\",\"Adhere strictly to corporate codes of conduct\"],\"selfScore\":5},{\"id\":\"OBJ_COMP_5\",\"text\":\"KPI Deployment for Team Members\",\"weight\":10,\"type\":\"competency\",\"expectedLevel\":4,\"category\":\"Leadership\",\"description\":[\"Clearly define and assign KPIs to direct reports\",\"Regularly monitor and evaluate team member performance\",\"Provide feedback and coaching to help team members achieve targets\"],\"selfScore\":4},{\"id\":\"OBJ_COMP_6\",\"text\":\"Self Improvement\",\"weight\":10,\"type\":\"competency\",\"expectedLevel\":4,\"category\":\"Self-Development\",\"description\":[\"Set personal development goals aligned with organizational objectives\",\"Actively seek feedback and opportunities to learn\",\"Complete training courses or obtain professional certifications\"],\"selfScore\":5}]','2026-07-20 12:21:57.000','1. Follow up on investors/partnership with SkillUp Academy in STEM.\\n2. Create STEM projects that attracts and propels prospective clients.\\n3. CBT opening for varieties of educational and technical vocational activities. etc.'),
('REV001MGR011','MGR011','Akinwale Akinola Samson','SU 1 (Program Coordinator)','CYC001','2026 Mid-Year Performance Cycle','Draft',NULL,NULL,NULL,0,'[{\"id\":\"OBJ_SU_SKILLUP_1\",\"text\":\"Program Planning & Coordination\",\"weight\":8,\"type\":\"objective\",\"departments\":[\"SU 1 (Program Coordinator)\"],\"description\":[\"Develop and implement training schedules and skill-up calendars for various cohorts, as well as courses offered at the Academy.\",\"Teach and coordinate soft and technical skills programs in line with Academy objectives.\",\"Manage enrollment and payment processes and class rosters and ensure learners have access to relevant resources.\",\"Organize in-person and virtual training sessions to accommodate learners\' different demands.\",\"Assist in recruiting and onboarding new instructors to meet program demands.\",\"Manage daily operations of Skill-up Academy, including scheduling, resource allocation, and staff management.\"]},{\"id\":\"OBJ_SU_SKILLUP_2\",\"text\":\"Instructor & Learner Engagement\",\"weight\":8,\"type\":\"objective\",\"departments\":[\"SU 1 (Program Coordinator)\"],\"description\":[\"Work closely with instructors to ensure smooth course delivery and learning experiences.\",\"Serves as a point of contact for learners, addressing any issues related to course content, schedules, or resources.\",\"Conduct regular feedback sessions with instructors and learners to monitor progress and areas of improvement.\",\"Motivate learners by tracking their progress and celebrating achievements.\"]},{\"id\":\"OBJ_SU_SKILLUP_3\",\"text\":\"Resource Management\",\"weight\":8,\"type\":\"objective\",\"departments\":[\"SU 1 (Program Coordinator)\"],\"description\":[\"Ensure all training materials, equipment, and resources are available during training sessions.\",\"Collaborate with instructors to update and improve course materials as needed.\"]},{\"id\":\"OBJ_SU_SKILLUP_4\",\"text\":\"Performance Tracking & Reporting\",\"weight\":8,\"type\":\"objective\",\"departments\":[\"SU 1 (Program Coordinator)\"],\"description\":[\"Analyze learner performance data and generate reports to measure the effectiveness of the training programs.\",\"Identify trends and suggest improvements to enhance the learning experience and overall program effectiveness.\",\"Report key performance metrics and end-of-cohort activities to the Program Coordinator at the end of every cohort training.\"]},{\"id\":\"OBJ_SU_SKILLUP_5\",\"text\":\"Partnership Development\",\"weight\":8,\"type\":\"objective\",\"departments\":[\"SU 1 (Program Coordinator)\"],\"description\":[\"Establish partnerships with industry professionals, organizations, and companies to provide learners with opportunities for internships, job placements, and real-world experience.\"]},{\"id\":\"OBJ_COMP_1\",\"text\":\"Leadership and Accountability\",\"weight\":10,\"type\":\"competency\",\"expectedLevel\":4,\"category\":\"Leadership\",\"description\":[\"Demonstrate responsibility and ownership of task outcomes\",\"Lead by example and guide colleagues\",\"Maintain accountability for deliverables\"]},{\"id\":\"OBJ_COMP_2\",\"text\":\"Initiative and Perseverance\",\"weight\":10,\"type\":\"competency\",\"expectedLevel\":4,\"category\":\"Behavioural\",\"description\":[\"Take proactive steps to resolve issues without waiting for instructions\",\"Persist in overcoming obstacles and difficulties\",\"Seek continuous improvements in workflows\"]},{\"id\":\"OBJ_COMP_3\",\"text\":\"Communication and Interpersonal Ability\",\"weight\":10,\"type\":\"competency\",\"expectedLevel\":4,\"category\":\"Behavioural\",\"description\":[\"Communicate clearly and effectively with team members and stakeholders\",\"Listen actively and cooperate well with others\",\"Build constructive work relationships\"]},{\"id\":\"OBJ_COMP_4\",\"text\":\"Work Ethics and Attendance\",\"weight\":10,\"type\":\"competency\",\"expectedLevel\":4,\"category\":\"Culture\",\"description\":[\"Show high reliability and commitment to work tasks\",\"Maintain consistent punctuality and attendance\",\"Adhere strictly to corporate codes of conduct\"]},{\"id\":\"OBJ_COMP_5\",\"text\":\"KPI Deployment for Team Members\",\"weight\":10,\"type\":\"competency\",\"expectedLevel\":4,\"category\":\"Leadership\",\"description\":[\"Clearly define and assign KPIs to direct reports\",\"Regularly monitor and evaluate team member performance\",\"Provide feedback and coaching to help team members achieve targets\"]},{\"id\":\"OBJ_COMP_6\",\"text\":\"Self Improvement\",\"weight\":10,\"type\":\"competency\",\"expectedLevel\":4,\"category\":\"Self-Development\",\"description\":[\"Set personal development goals aligned with organizational objectives\",\"Actively seek feedback and opportunities to learn\",\"Complete training courses or obtain professional certifications\"]}]','2026-07-15 14:29:04.000',NULL),
('REV001MGR012','MGR012','Bala Blessing','KHLC 2 (Supervisor)','CYC001','2026 Mid-Year Performance Cycle','Manager Reviewed','I ensured timely execution of all learning programmes by monitoring class schedules and supporting instructors. This term we achieved 90% of practicals and projects.\nAll missed classes were rescheduled within the same week to ensure pupils did not lose learning hours.\nI monitored team performance weekly through daily report, weekly report and WhatsApp check-ins. I conducted class observations this term and provided feedback to ensure instructors stayed on track.\n','Blessing, you have shown dedication and commitment to your role and have contributed positively to the successful coordination and delivery of our training programs. You demonstrate initiative, take ownership of your responsibilities, and are willing to go the extra mile to ensure tasks are completed. As you continue to grow, I encourage you to intentionally strengthen your leadership and communication skills. A supervisor\'s success is measured not only by personal performance but also by the ability to guide, influence, and develop the team. Becoming more proactive in supervising instructors, communicating expectations clearly, providing timely updates, and addressing issues early will significantly enhance your effectiveness and impact. I believe you have the potential to become a stronger leader, and I look forward to seeing you grow in these areas.\n\nIMPROVEMENT PLAN\n1. Improve communication by giving timely updates, sharing weekly progress reports, and escalating challenges early.\n2. Conduct regular check-ins with instructors and address performance issues promptly.\n3. Strengthen quality assurance by closely monitoring instructor performance and learner feedback.\n4. Continue developing your leadership capacity through training, mentorship, and intentional practice in influencing and motivating your team.',NULL,8.386,'[{\"id\":\"OBJ_COMP_1\",\"text\":\"Leadership and Accountability\",\"weight\":10,\"type\":\"competency\",\"expectedLevel\":4,\"category\":\"Leadership\",\"departments\":null,\"description\":[\"Demonstrate responsibility and ownership of task outcomes\",\"Lead by example and guide colleagues\",\"Maintain accountability for deliverables\"],\"selfScore\":5,\"managerScore\":4,\"comments\":null,\"evidence\":null,\"managerFeedback\":null},{\"id\":\"OBJ_COMP_2\",\"text\":\"Initiative and Perseverance\",\"weight\":10,\"type\":\"competency\",\"expectedLevel\":4,\"category\":\"Behavioural\",\"departments\":null,\"description\":[\"Take proactive steps to resolve issues without waiting for instructions\",\"Persist in overcoming obstacles and difficulties\",\"Seek continuous improvements in workflows\"],\"selfScore\":5,\"managerScore\":4,\"comments\":null,\"evidence\":null,\"managerFeedback\":\"Continue to take ownership of challenges with confidence, but be more intentional about identifying risks early and implementing preventive solutions. Regularly review existing processes, seek feedback from your team, and recommend improvements that enhance efficiency and program quality. As you grow in your leadership role, your ability to proactively drive improvements will be just as valuable as your ability to solve problems.\"},{\"id\":\"OBJ_COMP_3\",\"text\":\"Communication and Interpersonal Ability\",\"weight\":10,\"type\":\"competency\",\"expectedLevel\":4,\"category\":\"Behavioural\",\"departments\":null,\"description\":[\"Communicate clearly and effectively with team members and stakeholders\",\"Listen actively and cooperate well with others\",\"Build constructive work relationships\"],\"selfScore\":5,\"managerScore\":3,\"comments\":null,\"evidence\":null,\"managerFeedback\":\"Focus on communicating more proactively by providing regular updates, sharing progress and challenges early, and maintaining open communication with instructors and stakeholders. Consistent follow-up and active listening will help build stronger relationships, improve collaboration, and enable you to lead your team more effectively.\\n\\nPlease always submit your weekly reports.\"},{\"id\":\"OBJ_COMP_4\",\"text\":\"Work Ethics and Attendance\",\"weight\":10,\"type\":\"competency\",\"expectedLevel\":4,\"category\":\"Culture\",\"departments\":null,\"description\":[\"Show high reliability and commitment to work tasks\",\"Maintain consistent punctuality and attendance\",\"Adhere strictly to corporate codes of conduct\"],\"selfScore\":5,\"managerScore\":4,\"comments\":null,\"evidence\":null,\"managerFeedback\":null},{\"id\":\"OBJ_COMP_5\",\"text\":\"KPI Deployment for Team Members\",\"weight\":10,\"type\":\"competency\",\"expectedLevel\":4,\"category\":\"Leadership\",\"departments\":null,\"description\":[\"Clearly define and assign KPIs to direct reports\",\"Regularly monitor and evaluate team member performance\",\"Provide feedback and coaching to help team members achieve targets\"],\"selfScore\":4,\"managerScore\":4,\"comments\":null,\"evidence\":null,\"managerFeedback\":null},{\"id\":\"OBJ_COMP_6\",\"text\":\"Self Improvement\",\"weight\":10,\"type\":\"competency\",\"expectedLevel\":4,\"category\":\"Self-Development\",\"departments\":null,\"description\":[\"Set personal development goals aligned with organizational objectives\",\"Actively seek feedback and opportunities to learn\",\"Complete training courses or obtain professional certifications\"],\"selfScore\":4,\"managerScore\":4,\"comments\":null,\"evidence\":null,\"managerFeedback\":null},{\"id\":\"OBJ_KHLC_2_1\",\"text\":\"Program Execution & Delivery\",\"weight\":8,\"type\":\"objective\",\"expectedLevel\":null,\"category\":null,\"departments\":[\"KHLC 2 (Supervisor)\"],\"description\":[\"Ensure timely execution of all learning programmes within the term by delivering >=95% of programs\"],\"selfScore\":100,\"managerScore\":80,\"comments\":null,\"evidence\":null,\"managerFeedback\":null},{\"id\":\"OBJ_KHLC_2_2\",\"text\":\"Participant Engagement & Attendance\",\"weight\":8,\"type\":\"objective\",\"expectedLevel\":null,\"category\":null,\"departments\":[\"KHLC 2 (Supervisor)\"],\"description\":[\"Ensure at least 90% participation (internal and external teams) in the execution of each program\"],\"selfScore\":100,\"managerScore\":80,\"comments\":null,\"evidence\":null,\"managerFeedback\":null},{\"id\":\"OBJ_KHLC_2_3\",\"text\":\"Professional Development\",\"weight\":8,\"type\":\"objective\",\"expectedLevel\":null,\"category\":null,\"departments\":[\"KHLC 2 (Supervisor)\"],\"description\":[\"Complete at least 2 professional courses annually to improve skills and knowledge relevant to program coordination.\"],\"selfScore\":90,\"managerScore\":90,\"comments\":null,\"evidence\":null,\"managerFeedback\":null},{\"id\":\"OBJ_KHLC_2_4\",\"text\":\"Instructor Management & Quality Assurance\",\"weight\":8,\"type\":\"objective\",\"expectedLevel\":null,\"category\":null,\"departments\":[\"KHLC 2 (Supervisor)\"],\"description\":[\"90% participant satisfaction ratings in post-session feedback on subject matter expertise\",\"95% adherence to class schedules without significant delays or cancellations\",\"Zero incidents of reported unprofessional conduct during the term\",\"Problem solving/ Thinking outside the box during execution of programs\"],\"selfScore\":90,\"managerScore\":70,\"comments\":null,\"evidence\":null,\"managerFeedback\":\"You have demonstrated commitment to coordinating instructors and ensuring program delivery; however, there is room for improvement in instructor supervision and quality assurance. During the review period, there were incidents involving instructors that highlighted the need for closer monitoring, more proactive communication, and timely intervention. As a supervisor, it is important to provide clear expectations, conduct regular check-ins, and address performance concerns before they escalate. Additionally, continue to strengthen your problem-solving skills by anticipating challenges and implementing effective solutions during program execution. \\nFocusing on these areas will improve instructor performance, learner satisfaction, and the overall quality of our training programs.\"},{\"id\":\"OBJ_KHLC_2_5\",\"text\":\"Team Performance Feedback\",\"weight\":8,\"type\":\"objective\",\"expectedLevel\":null,\"category\":null,\"departments\":[\"KHLC 2 (Supervisor)\"],\"description\":[\"Ensure 100% of team members receive formal performance feedback at least once per quarter\"],\"selfScore\":100,\"managerScore\":80,\"comments\":null,\"evidence\":null,\"managerFeedback\":null}]','2026-07-17 09:41:04.000','\n\n1Communication & Follow-through Strengthen early communication channels and ensure all staff are clearly briefed ahead of critical school events to prevent lapses in attendance and representation.\n\nProactive Monitoring: Improve real-time monitoring of staff commitment during major events. Put structures in place for immediate escalation and backup plans.\n\nStaff Development: Continue building capacity of instructors in ICT, Robotics, and technology-driven teaching methods to enhance student engagement.\nImplement a weekly check-in and event reminder system for all staff.\n\n'),
('REV001MGR013','MGR013','Adedokun Khaleed Oluwatobiloba','KHLC 2 (Supervisor)','CYC001','2026 Mid-Year Performance Cycle','Manager Reviewed','','You have shown commitment to your responsibilities and have contributed positively to the team\'s objectives. Your dedication and willingness to get the work done are appreciated. As you continue to grow in your supervisory role, I encourage you to place greater emphasis on communication and timely reporting. Providing consistent weekly updates on completed activities, team progress, and marketing outcomes will improve visibility, support better decision-making, and strengthen accountability across the team. \\nDeveloping this habit will not only enhance team coordination but also position you as a more effective and dependable leader. I am confident that with greater consistency in these areas, you will continue to grow and make an even greater impact.',NULL,8.833333333333332,'[{\"id\":\"OBJ_COMP_1\",\"text\":\"Leadership and Accountability\",\"weight\":10,\"type\":\"competency\",\"expectedLevel\":4,\"category\":\"Leadership\",\"departments\":null,\"description\":[\"Demonstrate responsibility and ownership of task outcomes\",\"Lead by example and guide colleagues\",\"Maintain accountability for deliverables\"],\"selfScore\":5,\"managerScore\":4,\"comments\":null,\"evidence\":null,\"managerFeedback\":null},{\"id\":\"OBJ_COMP_2\",\"text\":\"Initiative and Perseverance\",\"weight\":10,\"type\":\"competency\",\"expectedLevel\":4,\"category\":\"Behavioural\",\"departments\":null,\"description\":[\"Take proactive steps to resolve issues without waiting for instructions\",\"Persist in overcoming obstacles and difficulties\",\"Seek continuous improvements in workflows\"],\"selfScore\":5,\"managerScore\":4,\"comments\":null,\"evidence\":null,\"managerFeedback\":null},{\"id\":\"OBJ_COMP_3\",\"text\":\"Communication and Interpersonal Ability\",\"weight\":10,\"type\":\"competency\",\"expectedLevel\":4,\"category\":\"Behavioural\",\"departments\":null,\"description\":[\"Communicate clearly and effectively with team members and stakeholders\",\"Listen actively and cooperate well with others\",\"Build constructive work relationships\"],\"selfScore\":5,\"managerScore\":4,\"comments\":null,\"evidence\":null,\"managerFeedback\":null},{\"id\":\"OBJ_COMP_4\",\"text\":\"Work Ethics and Attendance\",\"weight\":10,\"type\":\"competency\",\"expectedLevel\":4,\"category\":\"Culture\",\"departments\":null,\"description\":[\"Show high reliability and commitment to work tasks\",\"Maintain consistent punctuality and attendance\",\"Adhere strictly to corporate codes of conduct\"],\"selfScore\":5,\"managerScore\":4,\"comments\":null,\"evidence\":null,\"managerFeedback\":null},{\"id\":\"OBJ_COMP_5\",\"text\":\"KPI Deployment for Team Members\",\"weight\":10,\"type\":\"competency\",\"expectedLevel\":4,\"category\":\"Leadership\",\"departments\":null,\"description\":[\"Clearly define and assign KPIs to direct reports\",\"Regularly monitor and evaluate team member performance\",\"Provide feedback and coaching to help team members achieve targets\"],\"selfScore\":5,\"managerScore\":5,\"comments\":null,\"evidence\":null,\"managerFeedback\":null},{\"id\":\"OBJ_COMP_6\",\"text\":\"Self Improvement\",\"weight\":10,\"type\":\"competency\",\"expectedLevel\":4,\"category\":\"Self-Development\",\"departments\":null,\"description\":[\"Set personal development goals aligned with organizational objectives\",\"Actively seek feedback and opportunities to learn\",\"Complete training courses or obtain professional certifications\"],\"selfScore\":5,\"managerScore\":4,\"comments\":null,\"evidence\":null,\"managerFeedback\":null},{\"id\":\"OBJ_KHLC_2_1\",\"text\":\"Program Execution \\u0026 Delivery\",\"weight\":8,\"type\":\"objective\",\"expectedLevel\":null,\"category\":null,\"departments\":[\"KHLC 2 (Supervisor)\"],\"description\":[\"Ensure timely execution of all learning programmes within the term by delivering \\u003e=95% of programs\"],\"selfScore\":null,\"managerScore\":null,\"comments\":null,\"evidence\":null,\"managerFeedback\":null},{\"id\":\"OBJ_KHLC_2_2\",\"text\":\"Participant Engagement \\u0026 Attendance\",\"weight\":8,\"type\":\"objective\",\"expectedLevel\":null,\"category\":null,\"departments\":[\"KHLC 2 (Supervisor)\"],\"description\":[\"Ensure at least 90% participation (internal and external teams) in the execution of each program\"],\"selfScore\":null,\"managerScore\":null,\"comments\":null,\"evidence\":null,\"managerFeedback\":null},{\"id\":\"OBJ_KHLC_2_3\",\"text\":\"Professional Development\",\"weight\":8,\"type\":\"objective\",\"expectedLevel\":null,\"category\":null,\"departments\":[\"KHLC 2 (Supervisor)\"],\"description\":[\"Complete at least 2 professional courses annually to improve skills and knowledge relevant to program coordination.\"],\"selfScore\":null,\"managerScore\":null,\"comments\":null,\"evidence\":null,\"managerFeedback\":null},{\"id\":\"OBJ_KHLC_2_4\",\"text\":\"Instructor Management \\u0026 Quality Assurance\",\"weight\":8,\"type\":\"objective\",\"expectedLevel\":null,\"category\":null,\"departments\":[\"KHLC 2 (Supervisor)\"],\"description\":[\"90% participant satisfaction ratings in post-session feedback on subject matter expertise\",\"95% adherence to class schedules without significant delays or cancellations\",\"Zero incidents of reported unprofessional conduct during the term\",\"Problem solving/ Thinking outside the box during execution of programs\"],\"selfScore\":null,\"managerScore\":null,\"comments\":null,\"evidence\":null,\"managerFeedback\":null},{\"id\":\"OBJ_KHLC_2_5\",\"text\":\"Team Performance Feedback\",\"weight\":8,\"type\":\"objective\",\"expectedLevel\":null,\"category\":null,\"departments\":[\"KHLC 2 (Supervisor)\"],\"description\":[\"Ensure 100% of team members receive formal performance feedback at least once per quarter\"],\"selfScore\":null,\"managerScore\":null,\"comments\":null,\"evidence\":null,\"managerFeedback\":null}]','2026-07-15 15:49:17.000','\\n\\nImprovement Plan\\n1. Submit weekly activity and marketing reports consistently and on time.\\n2. Provide regular updates on team progress, challenges, and achievements.\\n3. Improve communication by proactively sharing information and escalating issues early.\\n4.  Maintain accurate documentation of marketing activities and outcomes to support performance tracking and decision-making.');
